// gate (`repokit protocol --check`, run by `repokit verify`) fails the build on drift.
//
// These are the wire shapes ONLY. The decode gates and the reading conveniences the
// app has always had live in hand-written extensions beside this file, so the wire
// half regenerates without touching a call site.
//
// Owner context: tools/ide — generated protocol types (ADR-341 D5).

import Foundation

/// The Sharpee-aware project tree, produced by running the story's world construction and
/// projecting the resulting entities. A flat entity list plus a build-status header; the
/// IDE buckets into categories client-side from `EntityNode.category`.
struct ProjectManifest: Codable, Equatable, Sendable {
    /// Schema version; equals `SCHEMA_VERSION` for manifests this package emits.
    let schemaVersion: Int
    /// Story id (from StoryConfig).
    let story: String
    /// Which path produced this manifest.
    let generatedFrom: ProjectManifest.GeneratedFrom
    /// Every introspected entity, in world-enumeration order.
    let entities: [EntityNode]
    /// Version of the narrow staging surface Chord text hatches can touch (design.md §5.6;
    /// story-loader's HATCH_CONTEXT_VERSION). A property of the emitting platform, stamped
    /// by the emitter — lets the IDE state exactly what a hatch *can* see without reading
    /// hatch code. Optional: absent from manifests emitted before the field existed.
    let hatchContextVersion: Int?

    enum GeneratedFrom: String, Codable, Equatable, Sendable {
        case cli
        case bridge
    }
}

/// Top-level project-tree categories. Doors/exits surface under a room's `exits`.
enum EntityCategory: String, Codable, Equatable, Sendable {
    case room
    case object
    case npc
    case region
}

/// One introspected world entity.
struct EntityNode: Codable, Equatable, Sendable {
    /// World entity id.
    let id: String
    /// IdentityTrait name (authored text) — the tree label.
    let displayName: String
    /// Derived from the runtime trait set (see ADR-184 derivation table).
    let category: EntityCategory
    /// Trait-type → the IDE-relevant fields (a projection, not the full trait).
    let traits: TraitSummary
    /// file:line from the tree-sitter name index; absent when unresolved.
    let source: SourceRef?
}

/// A resolved source location for an entity's creation site.
struct SourceRef: Codable, Equatable, Sendable {
    /// Workspace-relative path.
    let file: String
    /// 1-based line of the `createEntity('<name>', …)` site.
    let line: Int
    /// `'scope'` = fell back to the enclosing function (non-unique name).
    let resolution: SourceRef.Resolution

    enum Resolution: String, Codable, Equatable, Sendable {
        case exact
        case scope
    }
}

/// The fields the IDE renders/lints on, keyed by trait type. Sparse: a key is present only
/// if the entity carries that trait. The index signature keeps the shape forward-compatible
/// — unknown traits pass through without dropping the entity.
struct TraitSummary: Codable, Equatable, Sendable {
    let identity: TraitSummary.Identity?
    /// Exit directions present — drives the "room with no exits" lint.
    let room: TraitSummary.Room?
    /// Co-trait lint inputs (e.g. "lockable without openable").
    let container: TraitSummary.Container?

    struct Identity: Codable, Equatable, Sendable {
        let description: String?
    }

    struct Room: Codable, Equatable, Sendable {
        let exits: [String]
    }

    struct Container: Codable, Equatable, Sendable {
        let openable: Bool
        let lockable: Bool
    }
}

enum ComposeSeverity: String, Codable, Equatable, Sendable {
    case error
    case warning
}

/// A half-open region of story source. Lines and columns are 1-based. `file` names the
/// source file when it is NOT the file handed to `compile()`: an imported fragment's spans
/// carry the import path as the author wrote it plus `.chord` (`regions/harbor.chord`),
/// relative to the main file's directory — the same string the import resolver receives.
/// Absent means the main file. It is stamped at splice time, never by the lexer or parser
/// (ADR-251 D6, amended 2026-08-22).
struct DiagnosticSpan: Codable, Equatable, Sendable {
    /// Source file, relative to the main file's directory; absent = the main file.
    let file: String?
    /// 1-based line of the first character.
    let line: Int
    /// 1-based column of the first character.
    let column: Int
    /// 1-based line of the last character (inclusive).
    let endLine: Int
    /// 1-based column just past the last character.
    let endColumn: Int
}

/// One record in the payload's unified diagnostics stream (ADR-276 D4). `span` is present
/// exactly for compile diagnostics — hatch findings (`hatch.*` codes) carry a file+line
/// site only, no end-span.
struct ComposeDiagnosticRecord: Codable, Equatable, Sendable {
    let severity: ComposeSeverity
    /// Stable machine code — `parse.*`/`analysis.*`, or `hatch.*` for lint findings.
    let code: String
    let message: String
    /// Site file: the `.story` file for compile diagnostics, the hatch module for hatch
    /// findings.
    let file: String
    /// 1-based line of the site.
    let line: Int
    /// Full source span — compile diagnostics only (the underline range, ADR-258 D5).
    let span: DiagnosticSpan?
}

/// The `compose --json` stdout payload (ADR-258 D5).
struct ComposeJsonPayload: Codable, Equatable, Sendable {
    /// Equals `COMPOSE_JSON_SCHEMA_VERSION` for payloads this package's emitters write.
    let schemaVersion: Int
    /// The one diagnostics stream: compile diagnostics first, then hatch records.
    let diagnostics: [ComposeDiagnosticRecord]
    /// The Story IR the project tree is sourced from (ADR-258 D6). Present iff the compile
    /// succeeded AND the mode emits IR (`--json` without `--check`); absent under `--json
    /// --check` and whenever the compile failed — the payload never carries a non-`ok` IR
    /// (atomic load, ADR-210).
    let ir: ComposeStoryIR?
}

/// The subset of the Story IR the native shells decode (ADR-258 D6). A member is required
/// here only when the shell cannot run without it; everything the shell tolerates as absent
/// stays optional, so a truncated payload degrades rather than failing the whole decode.
struct ComposeStoryIR: Codable, Equatable, Sendable {
    /// IR format stamp — the shell's hard wire gate.
    let format: String
    /// Chord LANGUAGE version that compiled this story (ADR-257, informational).
    let languageVersion: String
    let meta: ComposeStoryIR.Meta
    /// Present exactly when the source carried a `grammar` header (ADR-269 D8): the file is
    /// a grammar file, so Build and Play are disabled for it.
    let grammarFile: ComposeStoryIR.GrammarFile?
    /// Authored entities, each with its exact source span (D6 navigation).
    let entities: [ComposeStoryIR.Entity]?
    /// `define action` blocks — the tree content for grammar files.
    let actions: [ComposeStoryIR.ActionDef]?
    /// The phrasebook — the Index lists KEYS only; bodies stay opaque.
    let phrases: ComposeStoryIR.PhraseBook?
    /// Declared hatch modules.
    let hatches: [ComposeStoryIR.Hatch]?

    /// Story-block metadata: the title, plus the header fields the shells read.
    struct Meta: Codable, Equatable, Sendable {
        /// Top-level by contract — the window title reads this directly (ADR-279 A1).
        let title: String
        let fields: ComposeStoryIR.Fields
    }

    /// The subset of `IRStoryFields` the shells consume. `id` names the `dist/web/<id>/`
    /// bundle directory; `storyVersion` and `authors` feed the build report's byline.
    struct Fields: Codable, Equatable, Sendable {
        let id: String?
        let storyVersion: String?
        let authors: [String]
    }

    /// A grammar file's declared name (ADR-269 D8).
    struct GrammarFile: Codable, Equatable, Sendable {
        let name: String
    }

    /// One authored entity: name, kind memberships, playable marker, region members, and
    /// the exact span of its `create` block.
    struct Entity: Codable, Equatable, Sendable {
        let id: String
        let name: String
        /// `playable` (ADR-327 D10) — this character may hold the player role. Who holds it
        /// is decided by the start block at runtime and is not on the IR.
        let isPlayable: Bool
        let kinds: [ComposeStoryIR.Kind]
        /// Region membership (`containing …`, ADR-236) — resolved member entity ids,
        /// non-empty only on region-kind entities.
        let containing: [ComposeStoryIR.ContainedMember]?
        let span: DiagnosticSpan
    }

    /// A kind membership (`a room`, `a person`, …).
    struct Kind: Codable, Equatable, Sendable {
        let name: String
    }

    /// One resolved `containing` member (a room or nested region).
    struct ContainedMember: Codable, Equatable, Sendable {
        let id: String
    }

    /// A `define action` block with its exact span.
    struct ActionDef: Codable, Equatable, Sendable {
        let name: String
        let span: DiagnosticSpan
    }

    /// A declared hatch module.
    struct Hatch: Codable, Equatable, Sendable {
        let name: String
        let modulePath: String
        let span: DiagnosticSpan?
    }

    /// The phrasebook: locale → phrase key → the phrase's span. Phrase bodies (strategies,
    /// variants) are deliberately not projected — the Index lists names; prose stays in the
    /// editor.
    struct PhraseBook: Codable, Equatable, Sendable {
        let defaultLocale: String
        let locales: [String: [String: ComposeStoryIR.PhraseEntry]]
    }

    /// One phrase key's source location.
    struct PhraseEntry: Codable, Equatable, Sendable {
        let span: DiagnosticSpan?
    }
}
